
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_cs_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_cs", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.782762752568838e-02, 9.697701518920993e-06, -1.226527541970637e-02, -2.063061398742903e-02, -2.618933508130156e-02, -2.965336806448625e-02, -3.142489532928706e-02, -3.164958439009697e-02, -3.048805468359560e-02, -3.110353734349080e-02, -5.731645702264663e-02, -5.455382522107803e-02, -2.756154303443705e-02, -2.286344621388543e-02, -1.812734350050465e-02, -1.153678170800084e-02, -4.782411439795027e-03, -9.274660311737198e-04, -7.132244177750793e-05, -1.745175130844257e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


